fn solve(input: Vec<i8>) -> Vec<i8> {
    // If fewer than three elements, no pouring can be described.
    if input.len() < 3 {
        return Vec::new();
    }
    // Unpack the first three values.
    let capacity = input[0] as i16;
    let current = input[1] as i16;
    let incoming = input[2] as i16;

    // Compute how much free space remains.
    let free_space = capacity - current;
    // Compute how much would overflow.
    let overflow = incoming - free_space;
    // Leftover is max(0, overflow).
    let leftover = if overflow > 0 { overflow } else { 0 };

    // Clamp to the i8 range just in case.
    let clamped = leftover.clamp(i8::MIN as i16, i8::MAX as i16) as i8;

    vec![clamped]
}

